// Build the OpenAI request. The prompt and schema come from extraction/ in the repo.
const config = $('Config').first().json;
const upload = $('Validate upload').first().json;

const PROMPT = "You extract data from supplier invoices for an accounts payable system.\n\nYou will receive one invoice as a PDF. It may be a clean digital PDF or a scanned image. Return the data in the required JSON format.\n\nRules:\n1. Copy values exactly as printed. Never fix, recalculate or fill in numbers. If the line items don't add up to the subtotal, or the total is wrong, return what is printed anyway. A separate system checks the math.\n2. If a field isn't on the invoice, return null. Never guess a PO number, date or amount.\n3. Dates: return YYYY-MM-DD. Read European dates (DD.MM.YYYY) correctly, so 30.10.2026 is 2026-10-30.\n4. Amounts: return plain numbers with a dot for decimals and no currency symbols or thousands separators. European \"2.904,00 \u20ac\" is 2904.00. US \"$1,240.50\" is 1240.50.\n5. Currency: return the 3-letter ISO code (USD, EUR, GBP). Use the currency field or symbol printed on the invoice.\n6. vendor_name is the company that sent the invoice, not the company being billed.\n7. tax is the total tax amount (sales tax, VAT, GST). Return 0 if the invoice shows no tax or a tax line of zero.\n8. line_items: include every line item on every page, in order. quantity and unit_price can be null if not printed. amount is the line total as printed.\n9. confidence: for each field, give a number from 0 to 1 for how sure you are that your answer is correct. Use 0.95 or higher only when the text is clear. Use lower scores when the text is blurry, cut off or ambiguous. If a field is clearly not on the invoice and you returned null, that is a correct answer, so give it high confidence. Confidence is about reading accuracy, not about whether the invoice is complete.\n10. notes: one short sentence about anything unusual (for example a payment reminder, a \"copy\" stamp, handwriting, or a missing PO number). Otherwise null.";
const SCHEMA = {"type": "object", "additionalProperties": false, "required": ["vendor_name", "vendor_email", "invoice_number", "invoice_date", "due_date", "po_number", "currency", "subtotal", "tax", "total", "line_items", "confidence", "notes"], "properties": {"vendor_name": {"type": ["string", "null"]}, "vendor_email": {"type": ["string", "null"]}, "invoice_number": {"type": ["string", "null"]}, "invoice_date": {"type": ["string", "null"], "description": "YYYY-MM-DD"}, "due_date": {"type": ["string", "null"], "description": "YYYY-MM-DD"}, "po_number": {"type": ["string", "null"]}, "currency": {"type": ["string", "null"], "description": "ISO 4217 code, e.g. USD"}, "subtotal": {"type": ["number", "null"]}, "tax": {"type": ["number", "null"]}, "total": {"type": ["number", "null"]}, "line_items": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["description", "quantity", "unit_price", "amount"], "properties": {"description": {"type": "string"}, "quantity": {"type": ["number", "null"]}, "unit_price": {"type": ["number", "null"]}, "amount": {"type": "number"}}}}, "confidence": {"type": "object", "additionalProperties": false, "required": ["vendor_name", "invoice_number", "invoice_date", "due_date", "po_number", "currency", "subtotal", "tax", "total", "line_items"], "properties": {"vendor_name": {"type": "number"}, "invoice_number": {"type": "number"}, "invoice_date": {"type": "number"}, "due_date": {"type": "number"}, "po_number": {"type": "number"}, "currency": {"type": "number"}, "subtotal": {"type": "number"}, "tax": {"type": "number"}, "total": {"type": "number"}, "line_items": {"type": "number"}}}, "notes": {"type": ["string", "null"]}}};

const body = {
  model: config.model,
  instructions: PROMPT,
  input: [{
    role: 'user',
    content: [
      { type: 'input_file', filename: upload.file_name, file_data: 'data:application/pdf;base64,' + upload.pdf_base64 },
      { type: 'input_text', text: 'Extract the data from this invoice.' },
    ],
  }],
  text: { format: { type: 'json_schema', name: 'invoice', schema: SCHEMA, strict: true } },
  reasoning: { effort: config.reasoning_effort },
};

return [{ json: { body, started_at: Date.now() } }];

// Turn the AI response into database rows. Values are saved exactly as the AI read them;
// checking the math, duplicates and POs happens in the validation step.
const config = $('Config').first().json;
const invoiceId = $('Create invoice row').first().json.id;
const startedAt = $('Build AI request').first().json.started_at;
const response = $input.first().json;

const message = (response.output || []).find(o => o.type === 'message');
const text = message?.content?.find(c => c.type === 'output_text')?.text;
if (!text) throw new Error('AI response had no text output');
const data = JSON.parse(text);

const isoDate = v => (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null);
const currency = v => (typeof v === 'string' && /^[A-Z]{3}$/.test(v.toUpperCase()) ? v.toUpperCase() : null);

const usage = response.usage || {};
const cached = usage.input_tokens_details?.cached_tokens || 0;
const price = config.price_per_million;
const costUsd = ((usage.input_tokens - cached) * price.input + cached * price.cached + usage.output_tokens * price.output) / 1e6;
const minConfidence = Math.min(...Object.values(data.confidence));

return [{
  json: {
    invoice_id: invoiceId,
    patch: {
      status: 'extracted',
      vendor_name_raw: data.vendor_name,
      invoice_number: data.invoice_number,
      invoice_date: isoDate(data.invoice_date),
      due_date: isoDate(data.due_date),
      currency: currency(data.currency),
      subtotal: data.subtotal,
      tax: data.tax,
      total: data.total,
      po_number: data.po_number,
      confidence: data.confidence,
      raw_extraction: data,
    },
    line_items: (data.line_items || []).map((li, i) => ({
      invoice_id: invoiceId,
      position: i + 1,
      description: li.description,
      quantity: li.quantity ?? 1,
      unit_price: li.unit_price,
      amount: li.amount,
    })),
    event: {
      invoice_id: invoiceId,
      step: 'extracted',
      actor: 'ai',
      details: {
        model: config.model,
        seconds: Math.round((Date.now() - startedAt) / 100) / 10,
        input_tokens: usage.input_tokens,
        output_tokens: usage.output_tokens,
        cost_usd: Math.round(costUsd * 1e6) / 1e6,
        min_confidence: minConfidence,
        notes: data.notes,
      },
    },
    min_confidence: minConfidence,
    extracted: data,
  },
}];
